"""Steel imports post: verify the flat-steel safeguard duty schedule against the customs notifications in the gazette."""
from gc3common import load, rep, insert_note, save, SRC
S = "india-imported-295-more-steel-this-year"
t = load(S)
t = rep(t, "<td>Provisional duty from 21 April 2025 (PIB 2123294), later confirmed for the full year</td>",
        "<td>Provisional 12% duty from 21 April 2025 for 200 days (No. 01/2025-Customs (SG)); it lapsed after 6 November 2025 and no duty applied until the final notification was published on 30 December 2025, which set 12% for the rest of the year</td>")
t = rep(t, "Finance ministry notification of 30 December 2025 (No. 02/2025-Customs (SG)), as summarised by trade and tax publications. One summary gives the second-year rate as 5%, which looks like an error; the gazette text was not read. The duty covers hot-rolled, cold-rolled, metallic-coated and colour-coated flat products. Imports above set CIF price thresholds,",
        "Finance ministry Notification No. 02/2025-Customs (SG) of 30 December 2025 (Gazette of India, Extraordinary, CG-DL-E-30122025-268941), " + SRC + ". It sets 12%, 11.5% and 11% for the three years; a trade summary that gave the second-year rate as 5% was wrong. The duty covers hot-rolled, cold-rolled, metallic-coated and colour-coated flat products. Imports at or above set CIF prices (US$675 a tonne for hot-rolled coils, sheets and plates, $695 for plate-mill plates, $824 for cold-rolled and $861 for metallic-coated),")
t = rep(t, "The date of the stainless steel exemption, the second-year duty rate in one summary and the April&ndash;August import total in some trade pieces conflict between sources;",
        "The date of the stainless steel exemption and the April&ndash;August import total in some trade pieces conflict between sources;")
t = rep(t, "The notification text, CBIC circular, CIF thresholds and country lists were not read; check them for any specific shipment.",
        "The safeguard notifications (No. 01/2025-Customs (SG), CG-DL-E-21042025-262579, and No. 02/2025-Customs (SG), CG-DL-E-30122025-268941) were " + SRC + "; the CBIC circular was not read, and the colour-coated CIF threshold is illegible in the OCR. Check the notification for any specific shipment.")
t = rep(t, "provisional 12% safeguard duty (21 April 2025, PIB 2123294).",
        "provisional 12% safeguard duty (21 April 2025, PIB 2123294). Gazette of India, Extraordinary: Ministry of Finance Notification No. 01/2025-Customs (SG), G.S.R. 243(E), 21 April 2025 (CG-DL-E-21042025-262579), and No. 02/2025-Customs (SG), 30 December 2025 (CG-DL-E-30122025-268941; egazette.gov.in/WriteReadData/2025/268941.pdf), " + SRC + ".")
t = insert_note(t, "The safeguard duty schedule has been checked against the customs notifications in the Gazette of India (No. 01/2025-Customs (SG) of 21 April 2025 and No. 02/2025-Customs (SG) of 30 December 2025). The rates are confirmed: 12%, then 11.5% from 21 April 2026, then 11% from 21 April 2027. One correction: the first-year duty was not continuous. The 12% provisional duty ran for 200 days from 21 April 2025, lapsed after 6 November 2025, and the final notification expressly levied no duty between then and its publication on 30 December 2025. The CIF price thresholds that exempt higher-priced imports are now given in the table note.")
save(S, t)
